import { useMemo, useState } from 'react';
import {
  JxBadge,
  JxButton,
  JxChip,
  JxEmptyState,
  JxPagination,
  JxProgressCircle,
} from '@jinx-ui/react';

type SpendStatus = 'active' | 'warning' | 'over' | 'archived';

type Project = {
  id: string;
  name: string;
  quotaUsedPercent: number;
  status: SpendStatus;
};

const PAGE_SIZE = 5;

const STATUS_META: Record<SpendStatus, { label: string; tone: 'success' | 'warning' | 'danger' | 'default' }> = {
  active: { label: 'В норме', tone: 'success' },
  warning: { label: 'Близко к лимиту', tone: 'warning' },
  over: { label: 'Превышение', tone: 'danger' },
  archived: { label: 'В архиве', tone: 'default' },
};

const STATUS_ORDER: SpendStatus[] = ['active', 'warning', 'over', 'archived'];

const PROJECTS: Project[] = [
  { id: 'p-01', name: 'Витрина маркетплейса', quotaUsedPercent: 42, status: 'active' },
  { id: 'p-02', name: 'Платёжный шлюз', quotaUsedPercent: 88, status: 'warning' },
  { id: 'p-03', name: 'Аналитика оттока пользователей', quotaUsedPercent: 117, status: 'over' },
  { id: 'p-04', name: 'Мобильное приложение курьера', quotaUsedPercent: 23, status: 'active' },
  { id: 'p-05', name: 'Поиск по каталогу', quotaUsedPercent: 76, status: 'warning' },
  { id: 'p-06', name: 'Экспорт отчётности в 1С', quotaUsedPercent: 9, status: 'archived' },
  { id: 'p-07', name: 'Рекомендательная лента', quotaUsedPercent: 64, status: 'active' },
  { id: 'p-08', name: 'Сервис нотификаций', quotaUsedPercent: 103, status: 'over' },
  { id: 'p-09', name: 'Кабинет партнёра', quotaUsedPercent: 51, status: 'active' },
  { id: 'p-10', name: 'Медиахранилище', quotaUsedPercent: 94, status: 'warning' },
  { id: 'p-11', name: 'Легаси-биллинг', quotaUsedPercent: 4, status: 'archived' },
  { id: 'p-12', name: 'A/B-платформа экспериментов', quotaUsedPercent: 37, status: 'active' },
];

export default function ProjectSpendPanel() {
  const [activeStatuses, setActiveStatuses] = useState<SpendStatus[]>(['active', 'warning', 'over']);
  const [page, setPage] = useState(1);

  const filtered = useMemo(
    () => (activeStatuses.length === 0 ? [] : PROJECTS.filter((p) => activeStatuses.includes(p.status))),
    [activeStatuses],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const visible = filtered.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  const toggleStatus = (status: SpendStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status],
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses(STATUS_ORDER);
    setPage(1);
  };

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        padding: '20px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <header style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
        <h2 style={{ margin: 0, fontFamily: 'var(--jx-font-display)', fontSize: '20px' }}>
          Расход по проектам
        </h2>
        <p style={{ margin: 0, color: 'var(--jx-text-2)', fontSize: '14px' }}>
          Заполненность квоты за текущий расчётный период.
        </p>
      </header>

      <div
        role="group"
        aria-label="Фильтры по статусу"
        style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}
      >
        {STATUS_ORDER.map((status) => {
          const selected = activeStatuses.includes(status);
          return (
            <JxChip
              key={status}
              active={selected}
              removable={selected}
              onRemove={() => toggleStatus(status)}
              onClick={() => toggleStatus(status)}
              onKeyDown={(event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault();
                  toggleStatus(status);
                }
              }}
              role="button"
              tabIndex={0}
              aria-pressed={selected}
            >
              {STATUS_META[status].label}
            </JxChip>
          );
        })}
      </div>

      {filtered.length === 0 ? (
        <JxEmptyState
          title="Под фильтры ничего не попало"
          message="Все статусы сняты или в них нет проектов. Верните фильтры, чтобы увидеть расход."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <ul
            style={{
              listStyle: 'none',
              margin: 0,
              padding: 0,
              display: 'flex',
              flexDirection: 'column',
              gap: '8px',
            }}
          >
            {visible.map((project) => (
              <li
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '16px',
                  padding: '12px 16px',
                  background: 'var(--jx-surface-2)',
                  border: '1px solid var(--jx-border)',
                  borderRadius: 'var(--jx-r)',
                }}
              >
                <JxProgressCircle
                  value={project.quotaUsedPercent}
                  showValue
                  aria-label={`Квота проекта «${project.name}» израсходована на ${project.quotaUsedPercent}%`}
                />
                <span
                  style={{
                    flex: '1 1 auto',
                    minWidth: 0,
                    fontSize: '15px',
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    whiteSpace: 'nowrap',
                  }}
                  title={project.name}
                >
                  {project.name}
                </span>
                <JxBadge tone={STATUS_META[project.status].tone} dot>
                  {STATUS_META[project.status].label}
                </JxBadge>
              </li>
            ))}
          </ul>

          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: '16px' }}>
            <span style={{ color: 'var(--jx-text-2)', fontSize: '13px' }}>
              Показано {visible.length} из {filtered.length}
            </span>
            {pageCount > 1 && (
              <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
            )}
          </div>
        </>
      )}
    </section>
  );
}

